def is_not_prime(n: int) -> bool:
    """
    Returns True if n is not a prime number, False otherwise.
    """
    if n <= 1:
        return True
    if n <= 3:
        return False
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def text_lowercase_underscore(text: str) -> bool:
    """
    Returns True if the input string contains sequences of lowercase letters joined with an underscore.
    """
    # Check if the string contains at least one underscore
    if '_' not in text:
        return False

    # Split the string by underscore and check if all parts are lowercase letters
    parts = text.split('_')
    for part in parts:
        if not part.islower() or not part:
            return False
    return True

def remove_dirty_chars(s1: str, s2: str) -> str:
    """
    Remove characters from s1 that are present in s2.
    """
    return ''.join(char for char in s1 if char not in s2)

def opposite_Signs(a, b):
    """
    Check whether the given two integers have opposite sign or not.
    """
    return (a > 0) != (b > 0)

def is_Monotonic(arr):
    if len(arr) <= 1:
        return True

    is_increasing = True
    is_decreasing = True

    for i in range(len(arr) - 1):
        if arr[i] > arr[i + 1]:
            is_increasing = False
        elif arr[i] < arr[i + 1]:
            is_decreasing = False

    return is_increasing and is_decreasing

def is_samepatterns(patterns1, patterns2):
    """
    Check if patterns1 is a permutation of patterns2.
    """
    if len(patterns1) != len(patterns2):
        return False

    # Sort both lists and compare
    return sorted(patterns1) == sorted(patterns2)

def merge_dictionaries_three(*dicts):
    """
    Merge three dictionaries into a single dictionary.
    If a key exists in multiple dictionaries, the last value wins.
    """
    merged = {}
    for d in dicts:
        merged.update(d)
    return merged

from collections import Counter

def freq_count(lst):
    """
    Returns a dictionary with the frequency of each element in the list.
    """
    return dict(Counter(lst))

def power(a, b):
    """
    Calculate a raised to the power of b.
    """
    if b == 0:
        return 1
    elif b == 1:
        return a
    elif b < 0:
        return 1 / power(a, -b)
    else:
        result = 1
        for _ in range(b):
            result *= a
        return result

# Test cases
assert power(3, 4) == 81
assert power(2, 3) == 8
assert power(5, 5) == 3125

def Find_Min_Length(lists):
    if not lists:
        return 0

    min_length = len(lists[0])
    for length in lists:
        if length < min_length:
            min_length = length
    return min_length

def decimal_to_binary(n: int) -> str:
    """Convert a decimal number to its binary equivalent as a string without leading zeros."""
    if n == 0:
        return '0'

    binary = ''
    while n > 0:
        binary = str(n % 2) + binary
        n //= 2

    return binary

def check_integer(s: str) -> bool:
    """
    Check if a string represents an integer.
    """
    return s.isdigit() or s.startswith('-') and s[1:].isdigit()

def string_to_list(s: str) -> list[str]:
    """Convert a string to a list of strings split on the space character."""
    return s.split(" ")

def sum(a, b):
    """
    Find the sum of common divisors of two given numbers.
    """
    def gcd(x, y):
        while y:
            x, y = y, x % y
        return x

    def common_divisors(n):
        divs = []
        for i in range(1, n + 1):
            if n % i == 0:
                divs.append(i)
        return divs

    common = set(common_divisors(a)) & set(common_divisors(b))
    return sum(common)

assert sum(10, 15) == 6
assert sum(100, 150) == 93
assert sum(4, 6) == 3

def magic_square_test(matrix):
    """
    Check if the given matrix is a magic square.
    A magic square is a square grid filled with distinct positive integers 
    (usually 1 to n^2) where the sum of the numbers in each row, column, 
    and both main diagonals are the same.
    """
    n = len(matrix)

    # Check if n is a perfect square
    if int(n**0.5) ** 2 != n:
        return False

    # Check if all elements are positive integers
    for row in matrix:
        if not all(isinstance(x, int) and x > 0 for x in row):
            return False

    # Check if all elements are distinct
    seen = set()
    for row in matrix:
        for x in row:
            if x in seen:
                return False
            seen.add(x)

    # Check if all elements are in the range [1, n^2]
    for row in matrix:
        for x in row:
            if not (1 <= x <= n * n):
                return False

    # Calculate the expected magic constant
    # Sum of all elements
    total_sum = sum(sum(row) for row in matrix)
    expected_sum = total_sum / n

    # Check if all rows, columns, and diagonals sum to the expected value
    for row in matrix:
        if sum(row) != expected_sum:
            return False

    for col in range(n):
        current_sum = 0
        for i in range(n):
            current_sum += matrix[i][col]
        if current_sum != expected_sum:
            return False

    # Check main diagonal
    if sum(matrix[i][i] for i in range(n)) != expected_sum:
        return False

    # Check anti-diagonal
    if sum(matrix[i][n - 1 - i] for i in range(n)) != expected_sum:
        return False

    return True
